#define MOD 1000000007LL

typedef long long ll;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char *grid = (char *)malloc((N + 5) * (N + 5));
    char buf[2005];

    ll *dpCnt = (ll *)calloc((size_t)N * N, sizeof(ll));
    ll *dpSum = (ll *)calloc((size_t)N * N, sizeof(ll));
    ll ans = 0;

    for (int i = 0; i < N; i++) {
        scanf("%s", buf);
        for (int j = 0; j < N; j++) {
            grid[i * N + j] = buf[j];
        }
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            char c = grid[i * N + j];
            if (c == '#') continue;

            ll d = c - '0';
            ll cnt = 0, sum = 0;

            if (i > 0 && grid[(i - 1) * N + j] != '#') {
                cnt += dpCnt[(i - 1) * N + j] + 1;
                sum += dpSum[(i - 1) * N + j] + d;
            }
            if (j > 0 && grid[i * N + (j - 1)] != '#') {
                cnt += dpCnt[i * N + (j - 1)] + 1;
                sum += dpSum[i * N + (j - 1)] + d;
            }
            if (i > 0 && j > 0 &&
                grid[(i - 1) * N + j] != '#' &&
                grid[i * N + (j - 1)] != '#' &&
                grid[(i - 1) * N + (j - 1)] != '#') {
                cnt -= dpCnt[(i - 1) * N + (j - 1)] + 1;
                sum -= dpSum[(i - 1) * N + (j - 1)] + d;
            }

            dpCnt[i * N + j] = cnt;
            dpSum[i * N + j] = sum;

            ans += d * sum;
        }
    }

    printf("%lld\n", ans);

    free(grid);
    free(dpCnt);
    free(dpSum);
    return 0;
}

