int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<string> grid(N);
    for (int i = 0; i < N; i++) {
        cin >> grid[i];
    }

    const int MOD = 1e9 + 7;
    // dp[i][j] = sum of digits of all cells reachable from (i,j) going right/down
    // cnt[i][j] = number of reachable cells from (i,j) (including itself? we'll handle separately)
    vector<vector<long long>> dp(N, vector<long long>(N, 0));
    vector<vector<long long>> cnt(N, vector<long long>(N, 0));

    long long ans = 0;

    for (int i = N - 1; i >= 0; i--) {
        for (int j = N - 1; j >= 0; j--) {
            if (grid[i][j] == '#') continue;
            int digit = grid[i][j] - '0';

            long long sumBelow = 0, cntBelow = 0;
            long long sumRight = 0, cntRight = 0;

            if (i + 1 < N && grid[i+1][j] != '#') {
                sumBelow = dp[i+1][j];
                cntBelow = cnt[i+1][j];
            }
            if (j + 1 < N && grid[i][j+1] != '#') {
                sumRight = dp[i][j+1];
                cntRight = cnt[i][j+1];
            }

            // combine contributions from right and below, avoiding double count of diagonal
            long long totalSum = (sumBelow + sumRight) % MOD;
            long long totalCnt = (cntBelow + cntRight) % MOD;

            // Add contributions from pairs (current cell, reachable cells)
            ans = (ans + digit * totalSum) % MOD;
            // Also add contributions from pairs among reachable cells already counted by dp? 
            // No: dp already includes contributions among them. We only add between current cell and reachable ones.

            // Now update dp and cnt for this cell
            dp[i][j] = (totalSum + digit) % MOD;
            cnt[i][j] = (totalCnt + 1) % MOD;
        }
    }

    cout << ans % MOD << "\n";
    return 0;
}

