int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<string> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    long long ans = 0;

    // dp[i][j] = sum of digits of all reachable predecessor cells of (i,j),
    // including the digit at (i,j) itself.
    vector<vector<long long>> dp(N, vector<long long>(N, 0));
    vector<vector<int>> up(N, vector<int>(N, 0));
    vector<vector<int>> leftc(N, vector<int>(N, 0));

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (a[i][j] == '#') continue;

            int d = a[i][j] - '0';

            long long fromUp = 0, fromLeft = 0, fromDiag = 0;
            if (i > 0 && a[i - 1][j] != '#') fromUp = dp[i - 1][j];
            if (j > 0 && a[i][j - 1] != '#') fromLeft = dp[i][j - 1];
            if (i > 0 && j > 0 && a[i - 1][j - 1] != '#') fromDiag = dp[i - 1][j - 1];

            // Inclusion-exclusion for cells that can reach current cell.
            dp[i][j] = fromUp + fromLeft - fromDiag + d;

            // All previous reachable cells X contribute digit(X) * d for pair (X, current).
            ans += (dp[i][j] - d) * d;
        }
    }

    cout << ans << '\n';
    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        sc.nextLine();
        char[][] board = new char[N][N];
        for (int i = 0; i < N; i++) {
            board[i] = sc.nextLine().toCharArray();
        }

        long[][] sumProd = new long[N][N];
        long[][] count = new long[N][N];
        long[][] sumDigits = new long[N][N];
        final long MOD = 1_000_000_007L;

        for (int i = N - 1; i >= 0; i--) {
            for (int j = N - 1; j >= 0; j--) {
                if (board[i][j] == '#') continue;
                int digit = board[i][j] - '0';

                long sp = 0, cnt = 0, sd = 0;

                // from down
                if (i + 1 < N && board[i + 1][j] != '#') {
                    sp = (sp + sumProd[i + 1][j]) % MOD;
                    cnt = (cnt + count[i + 1][j]) % MOD;
                    sd = (sd + sumDigits[i + 1][j]) % MOD;
                }
                // from right
                if (j + 1 < N && board[i][j + 1] != '#') {
                    sp = (sp + sumProd[i][j + 1]) % MOD;
                    cnt = (cnt + count[i][j + 1]) % MOD;
                    sd = (sd + sumDigits[i][j + 1]) % MOD;
                }

                // new pairs with current cell as X
                sp = (sp + digit * sd) % MOD;
                cnt = (cnt + 1) % MOD;
                sd = (sd + digit) % MOD;

                sumProd[i][j] = sp;
                count[i][j] = cnt;
                sumDigits[i][j] = sd;
            }
        }

        long total = 0;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (board[i][j] != '#') {
                    total = (total + sumProd[i][j]) % MOD;
                }
            }
        }
        System.out.println(total);
    }
}

