    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int[][] grid = new int[N][N];
        for (int i = 0; i < N; i++) {
            String line = br.readLine().trim();
            for (int j = 0; j < N; j++) {
                char c = line.charAt(j);
                grid[i][j] = (c == '#') ? -1 : (c - '0');
            }
        }
        long ans = 0;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (grid[i][j] <= 0) continue;
                boolean[][] reach = new boolean[N][N];
                Queue<int[]> q = new LinkedList<>();
                q.add(new int[]{i, j});
                reach[i][j] = true;
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    int r = cur[0], c = cur[1];
                    int[][] dirs = {{0,1},{1,0}};
                    for (int[] d : dirs) {
                        int nr = r+d[0], nc = c+d[1];
                        if (nr<N && nc<N && !reach[nr][nc] && grid[nr][nc] != -1) {
                            reach[nr][nc] = true;
                            q.add(new int[]{nr, nc});
                        }
                    }
                }
                for (int r = 0; r < N; r++)
                    for (int c = 0; c < N; c++)
                        if (reach[r][c] && (r != i || c != j) && grid[r][c] > 0)
                            ans += (long) grid[i][j] * grid[r][c];
            }
        }
        System.out.println(ans);
    }
}

import java.io.*;
