public class Main {
    static final long MOD = 1_000_000_007L; // not needed, just habit; unused

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        char[][] g = new char[N][];
        for (int i = 0; i < N; i++) g[i] = fs.next().toCharArray();

        long[][] colSum = new long[N][N];
        long[][] colCnt = new long[N][N];

        long answer = 0;

        for (int i = N - 1; i >= 0; i--) {
            long[] rowSum = new long[N];
            long[] rowCnt = new long[N];

            for (int j = N - 1; j >= 0; j--) {
                if (g[i][j] == '#') {
                    rowSum[j] = 0;
                    rowCnt[j] = 0;
                    colSum[i][j] = 0;
                    colCnt[i][j] = 0;
                    continue;
                }

                long rightSum = (j + 1 < N ? rowSum[j + 1] : 0);
                long rightCnt = (j + 1 < N ? rowCnt[j + 1] : 0);
                long downSum = (i + 1 < N ? colSum[i + 1][j] : 0);
                long downCnt = (i + 1 < N ? colCnt[i + 1][j] : 0);

                long interSum = 0;
                long interCnt = 0;
                if (i + 1 < N && j + 1 < N && g[i][j + 1] != '#' && g[i + 1][j] != '#') {
                    interSum = colSum[i + 1][j + 1];
                    interCnt = colCnt[i + 1][j + 1];
                }

                long reachableSum = rightSum + downSum - interSum;
                long reachableCnt = rightCnt + downCnt - interCnt;

                int digit = g[i][j] - '0';
                answer += (long) digit * reachableSum;

                rowSum[j] = digit + reachableSum;
                rowCnt[j] = 1 + reachableCnt;
                colSum[i][j] = rowSum[j];
                colCnt[i][j] = rowCnt[j];
            }
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    n = int(input_data[0])
    grid = []
    for i in range(1, n+1):
        grid.append(input_data[i])

    ans = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '#':
                continue
            # BFS from (i,j) going right/down
            val_x = int(grid[i][j]) if grid[i][j] != '.' else 0
            visited = [[False]*n for _ in range(n)]
            visited[i][j] = True
            q = deque([(i,j)])
            while q:
                r, c = q.popleft()
                for dr, dc in [(0,1),(1,0)]:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<n and 0<=nc<n and not visited[nr][nc] and grid[nr][nc]!='#':
                        visited[nr][nc] = True
                        q.append((nr,nc))
                        if grid[nr][nc] != '.':
                            ans += val_x * int(grid[nr][nc])
    print(ans)

solve()
